func TestOptionalNullableRoundTripAPICustomObject(t *testing.T) {
	optionalNullableKeys := []string{
		"custom_fields",
		"relations",
	}
	marshalToMap := func(t *testing.T, obj *APICustomObject) map[string]json.RawMessage {
		data, err := json.Marshal(obj)
		require.NoError(t, err, "marshaling should succeed")
		var result map[string]json.RawMessage
		require.NoError(t, json.Unmarshal(data, &result), "marshaled data should be a JSON object")
		return result
	}

	t.Run("NullPreserved", func(t *testing.T) {
		t.Parallel()
		var obj APICustomObject
		require.NoError(t, json.Unmarshal([]byte(`{"custom_fields":null,"relations":null}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range optionalNullableKeys {
			value, ok := result[key]
			require.True(t, ok, "optional nullable field %q received as null should be present in the output", key)
			assert.Equal(t, "null", string(value), "optional nullable field %q received as null should be null in the output", key)
		}
	})

	t.Run("AbsentStaysAbsent", func(t *testing.T) {
		t.Parallel()
		var obj APICustomObject
		require.NoError(t, json.Unmarshal([]byte(`{}`), &obj))
		result := marshalToMap(t, &obj)
		for _, key := range optionalNullableKeys {
			assert.NotContains(t, result, key, "optional nullable field %q absent from the input should be absent from the output", key)
		}
	})

	t.Run("FreshValueOmits", func(t *testing.T) {
		t.Parallel()
		result := marshalToMap(t, &APICustomObject{})
		for _, key := range optionalNullableKeys {
			assert.NotContains(t, result, key, "optional nullable field %q should be omitted from a freshly constructed value", key)
		}
	})
}

